'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var EPS = require( '@stdlib/constants/float64/eps' );
var abs = require( '@stdlib/math/base/special/abs' );
var bip = require( './../lib/bip.js' );


// FIXTURES //

var smallPositive = require( './fixtures/c/cephes/small_positive.json' );
var smallNegative = require( './fixtures/c/cephes/small_negative.json' );
var largePositive = require( './fixtures/c/cephes/large_positive.json' );
var largeNegative = require( './fixtures/c/cephes/large_negative.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof bip, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function evaluates the Airy function Bi\'(x) (large negative values)', function test( t ) {
	var expectedBip;
	var delta;
	var out;
	var tol;
	var x;
	var i;

	expectedBip = largeNegative.Bip;
	x = largeNegative.x;
	for ( i = 0; i < x.length; i++ ) {
		out = bip( x[i] );
		if ( out === expectedBip[i] ) {
			t.strictEqual( out, expectedBip[i], 'x: '+x[i]+', Bip: '+out+', expected: '+expectedBip[i] );
		} else {
			delta = abs( out - expectedBip[i] );
			tol = 30.0 * EPS * abs( expectedBip[i] );
			t.strictEqual( delta <= tol, true, 'within tolerance. x: '+x[i]+'. Bip: '+out+'. E: '+expectedBip[i]+'. Δ: '+delta+'. tol: '+tol+'.' );
		}
	}
	t.end();
});

