tape( 'the function returns `NaN` if provided `NaN`', function test( t ) {
	var v = bip( NaN );
	t.strictEqual( isnan( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns correct values if provided `+infinity`', function test( t ) {
	var v = bip( PINF );
	t.strictEqual( v, PINF, 'returns positive infinity' );
	t.end();
});

tape( 'the function returns correct values if provided `200.0`', function test( t ) {
	var v = bip( 200.0 );
	t.strictEqual( v, PINF, 'returns positive infinity' );
	t.end();
});

tape( 'the function returns correct values if provided `-infinity`', function test( t ) {
	var v = bip( NINF );
	t.strictEqual( isnan(v), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns correct values if provided `-1e308`', function test( t ) {
	var v = bip( NINF );
	t.strictEqual( isnan(v), true, 'returns expected value' );
	t.end();
});
